namespace androidx.text.emoji.flatbuffer;

table MetadataList {
    version : int;
    list : [MetadataItem];
    sourceSha : string;
}

table MetadataItem {
    id : int;
    emojiStyle : bool;
    sdkAdded : short;
    compatAdded : short;
    width : short;
    height : short;
    codepoints : [int];
}

root_type MetadataList;
